insert into public.words (id, word, romanization, category, secondary_category, short_desc, short_desc_i18n, pronunciation, meanings, origin, origin_i18n, usage, usage_i18n, related_words, likes, saves, translations) values
('483', '골반통신', 'Gol-ban-tong-sin', 'reels', null, '무슨 일이 있어도 골반춤은 멈추지 않는 숏폼 밈', '{"de": "Ein Kurzvideo-Meme, bei dem der Hüfttanz einfach nicht aufhört", "en": "A short-form meme where the hip dance keeps going no matter what happens", "es": "Un meme de vídeo corto en el que el baile de cadera no para pase lo que pase", "ja": "何があっても腰ダンスが止まらないショート動画ミーム", "vi": "Meme video ngắn: dù chuyện gì xảy ra thì điệu lắc hông vẫn không dừng"}'::jsonb, null, '[{"type": "명사", "examples": [{"de": "Den Hüfttanz auch noch auf einen Beerdigungsclip zu legen, war zu viel.", "es": "Meterle el baile de caderas hasta a un vídeo de funeral fue pasarse.", "ja": "葬式の映像にまで골반통신を付けるのはさすがにやりすぎ。", "vi": "Ghép điệu lắc hông vào cả clip đám tang thì hơi quá.", "eng": "Slapping the hip-dance edit onto a funeral clip was going too far.", "kor": "장례식 짤에까지 골반통신 붙이는 건 좀 심했다."}, {"de": "Was auch passiert, der bleibt auf Hüftkanal verbunden.", "es": "A este, pase lo que pase, no se le cae la conexión de caderas.", "ja": "こいつ何があっても골반통신に接続中だな。", "vi": "Thằng này có chuyện gì cũng vẫn đang kết nối kênh lắc hông.", "eng": "No matter what happens, this guy stays connected to the hip channel.", "kor": "얘는 무슨 일이 생겨도 골반통신 접속 중이야."}], "definition": "''말로 하는 소통이 아니라 골반의 움직임으로 통신한다''는 농담에서 나온 말로, 어떤 상황에 놓여도 등장인물이 계속 골반춤을 추는 영상 밈을 가리킨다. 실연 직후든 소개팅 자리든 감정과 상관없이 춤이 이어지고, 상황 설명 자막과 격렬한 움직임이 어긋나는 데서 웃음이 나온다. 기존 캐릭터나 유명인 영상에 골반 움직임만 편집해 붙이는 2차 창작도 많다.", "definition_i18n": {"de": "Vom Scherz, man kommuniziere nicht mit Worten, sondern mit der Hüftbewegung. Gemeint ist ein Video-Meme, in dem die Figur den Hüfttanz fortsetzt, egal was passiert — frisch verlassen, beim Blind Date, völlig egal. Der Witz liegt im Widerspruch zwischen der Untertitelbeschreibung und der unbeirrten Bewegung. Vieles ist Montage: Die Hüftbewegung wird auf Clips bekannter Figuren oder Promis gesetzt.", "en": "From the joke that you communicate not with words but with the motion of your pelvis. It names a video meme in which the subject keeps doing a hip dance no matter the situation — just dumped, on a blind date, whatever. The humour comes from the gap between the caption describing the scene and the relentless movement. A lot of it is edited: people graft the hip motion onto clips of existing characters or celebrities.", "es": "Del chiste de que uno se comunica no con palabras sino con el movimiento de la pelvis. Nombra un meme en vídeo donde el protagonista sigue bailando con las caderas pase lo que pase: recién plantado, en una cita a ciegas, da igual. La gracia está en el desajuste entre el rótulo que describe la escena y el movimiento imparable. Mucho es montaje: se injerta el meneo sobre clips de personajes o famosos ya existentes.", "ja": "「言葉ではなく骨盤の動きで通信する」という冗談から出た語で、どんな状況に置かれても登場人物が腰ダンスを続ける動画ミームを指す。失恋直後でも合コンの席でも感情と関係なく踊りが続き、状況説明の字幕と激しい動きがちぐはぐなところが笑いどころ。既存のキャラクターや有名人の映像に腰の動きだけ編集で足す二次創作も多い。", "vi": "Bắt nguồn từ câu đùa rằng người ta giao tiếp không bằng lời mà bằng chuyển động của hông. Nó chỉ thể loại meme video trong đó nhân vật cứ lắc hông bất kể hoàn cảnh — vừa bị đá, đang xem mắt, gì cũng vậy. Cái buồn cười nằm ở độ vênh giữa dòng phụ đề mô tả tình huống và điệu nhảy không ngừng. Phần lớn là dựng lại: người ta ghép chuyển động hông vào clip nhân vật hoặc người nổi tiếng có sẵn."}}]'::jsonb, '한 숏폼 크리에이터가 ''어떤 상황에서도 골반춤은 멈추지 않는다''는 콘셉트로 올린 챌린지 영상에서 시작됐다. ''골반통신에 접속하면 춤이 더 빨라진다''는 설정이 붙으면서 2025년 하반기 인스타그램 릴스를 중심으로 퍼졌다. 배경 음원이 정해져 있어 곡만 들어도 이 밈임을 알아보지만, 곡명을 밝힌 출처가 한 곳뿐이라 여기서는 적지 않는다. 최초 제작자로 특정 크리에이터를 지목한 출처들도 서로 인용 관계로 보여 이름을 확정하지 않는다.', '{"de": "Es begann mit dem Challenge-Video eines Kurzvideo-Creators nach dem Motto, der Hüfttanz höre nie auf, egal was sei. Als der Gag dazukam, dass man bei ''Verbindung zum Beckenkanal'' schneller tanzt, verbreitete es sich in der zweiten Hälfte 2025 über Instagram Reels. Ein fester Track macht das Meme schon am Ton erkennbar, doch nur eine Quelle nennt den Song, deshalb steht er hier nicht. Die Quellen, die einen bestimmten Creator nennen, zitieren offenbar einander — auch der Name bleibt daher offen.", "en": "It began with a challenge video by a short-form creator built on the concept that the hip dance never stops, whatever the situation. Once the bit about ''connecting to the pelvis channel makes you dance faster'' was added, it spread through Instagram Reels in the second half of 2025. A fixed backing track makes the meme recognisable from the music alone, but only one source names the song, so it is not recorded here. The sources that name a specific creator appear to be citing each other, so no name is fixed either.", "es": "Empezó con el vídeo-reto de un creador de formato corto bajo la premisa de que el baile de caderas no se detiene pase lo que pase. Cuando se añadió el gag de que ''conectarse al canal de la pelvis te hace bailar más rápido'', se extendió por Reels en la segunda mitad de 2025. Tiene una pista fija que delata el meme solo con oírla, pero únicamente una fuente nombra la canción, así que no se anota. Las fuentes que señalan a un creador concreto parecen citarse entre sí, de modo que tampoco se fija el nombre.", "ja": "あるショート動画クリエイターが「どんな状況でも腰ダンスは止まらない」というコンセプトで上げたチャレンジ動画が始まり。「골반통신に接続すると踊りが速くなる」という設定が加わり、2025年後半にインスタのリールを中心に広まった。決まった背景音源があり曲だけでこのミームと分かるが、曲名を挙げた出典が一つしかないためここには記さない。最初の制作者として特定のクリエイターを挙げる出典も互いに引用関係に見えるため、名前も確定しない。", "vi": "Khởi đầu từ video thử thách của một nhà sáng tạo video ngắn với ý tưởng rằng điệu lắc hông không bao giờ dừng, bất kể hoàn cảnh. Khi thêm chi tiết ''kết nối vào kênh hông thì nhảy nhanh hơn'', nó lan trên Instagram Reels nửa cuối 2025. Meme có nhạc nền cố định, chỉ nghe nhạc là nhận ra, nhưng chỉ một nguồn nêu tên bài hát nên ở đây không ghi. Các nguồn chỉ đích danh một creator dường như trích lẫn nhau nên cũng không khẳng định tên."}'::jsonb, '영상에 붙이는 말이라 대화보다 댓글·자막에서 본다. ''골반통신 접속 중''처럼 통신 비유를 이어 쓰는 것이 정석이다. 몸을 흔드는 밈이라 자리와 상대를 가려야 하고, 슬픈 상황 짤에 갖다 붙이는 건 이미 밈 안에서도 ''선 넘었다''는 소리를 듣는다. 직장이나 처음 보는 사람 앞에서 꺼낼 말은 아니다.', '{"de": "Es hängt an Videos, taucht also eher in Kommentaren und Untertiteln auf als im Gespräch. Üblich ist, die Telekom-Metapher weiterzuspinnen: ''mit dem Beckenkanal verbunden''. Da der Körper geschüttelt wird, sollte man die Situation abschätzen — auf traurige Clips gesetzt, gilt es schon im eigenen Publikum als Grenzüberschreitung. Nichts für die Arbeit oder für Fremde.", "en": "It attaches to videos, so you see it in comments and captions more than in speech. The standard move is to keep the telecom metaphor running: 골반통신 접속 중 (connected to the pelvis channel). Because it is a body-shaking meme, read the room — grafting it onto a sad clip already gets called out as crossing the line within the meme''s own audience. Not something to bring up at work or with strangers.", "es": "Va pegado a vídeos, así que aparece más en comentarios y rótulos que en el habla. Lo típico es mantener la metáfora de las telecomunicaciones: ''conectado al canal de caderas''. Al ser un meme de mover el cuerpo, conviene leer el ambiente; aplicarlo a un clip triste ya se considera pasarse incluso dentro del propio público del meme. No es cosa para el trabajo ni ante desconocidos.", "ja": "動画に添える語なので会話よりコメントや字幕で見かける。「골반통신 접속 중(接続中)」のように通信の比喩を続けるのが定番。体を揺らすミームなので場と相手は選ぶべきで、悲しい場面の映像に付けるのはミームの内輪でも「やりすぎ」と言われる。職場や初対面の相手の前で出す語ではない。", "vi": "Nó gắn với video nên xuất hiện trong bình luận và phụ đề nhiều hơn trong lời nói. Cách dùng chuẩn là tiếp tục ẩn dụ viễn thông: ''đang kết nối kênh hông''. Vì là meme lắc người nên phải xem hoàn cảnh — ghép vào clip buồn thì ngay trong cộng đồng meme cũng bị nói là quá lố. Không phải thứ đem ra ở chỗ làm hay trước người lạ."}'::jsonb, array['챌린지','밈','짤'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Pelvis channel (unstoppable hip-dance meme)"}, {"lang": "🇯🇵 JA", "text": "骨盤通信(止まらない腰ダンスミーム)"}, {"lang": "🇨🇳 ZH", "text": "骨盆通信(停不下来的扭胯梗)"}, {"lang": "🇻🇳 VI", "text": "Kênh lắc hông (meme nhảy hông không dừng)"}, {"lang": "🇪🇸 ES", "text": "Canal de caderas (meme del baile que no para)"}, {"lang": "🇩🇪 DE", "text": "Beckenkanal (Meme vom endlosen Hüfttanz)"}]'::jsonb);
